def set_format(name):
    """화면 형식 바꾸기 (쇼츠 세로 / 롱폼 가로). 미리보기 크기도 같이 바뀜"""
    global W, H, PREVIEW_W, PREVIEW_H
    W, H = FORMATS.get(name, FORMATS["쇼츠 세로(1080×1920)"])
    if W > H:
        PREVIEW_W, PREVIEW_H = 640, 360
    else:
        PREVIEW_W, PREVIEW_H = 360, 640
