def style_vec_ko(name):
    """화풍 이름 → 한국어 설명 (없으면 영어 지시 그대로)"""
    return IMAGE_STYLES_KO.get(name) or IMAGE_STYLES.get(name, "") or str(name)


ZIP_LIMIT = 20 * 1024 * 1024   # Gemini·ChatGPT 에 올릴 ZIP 한도


def make_prompt_zip(zip_path, samples, files_text, limit=ZIP_LIMIT):
    """화풍 샘플 그림 + 안내·프롬프트 글을 ZIP 하나로 (limit 를 넘지 않게 샘플을 줄이고, 그래도 크면 뒤 샘플부터 뺌)
    files_text: {"00_먼저_읽기.txt": "..."} → (경로, 바이트, 넣은 샘플 수)"""
    import zipfile
    ims = []
    for p in samples or []:
        try:
            im = Image.open(p)
            im.load()
            ims.append(im.convert("RGB"))
        except Exception:
            continue
    texts = {k: v.encode("utf-8") for k, v in files_text.items()}
    for side, q in ((1536, 88), (1280, 85), (1024, 80), (800, 75), (640, 70)):
        blobs = []
        for im in ims:
            c = im.copy()
            c.thumbnail((side, side), Image.LANCZOS)
            b = io.BytesIO()
            c.save(b, "JPEG", quality=q)
            blobs.append(b.getvalue())
        while True:
            total = sum(len(x) for x in blobs) + sum(len(x) for x in texts.values()) + 4096
            if total <= limit * 0.97 or not blobs:
                break
            if side > 640:
                break
            blobs.pop()                      # 가장 작게 줄여도 넘치면 뒤 샘플부터 뺌
        if total <= limit * 0.97:
            break
    os.makedirs(os.path.dirname(zip_path) or ".", exist_ok=True)
    with zipfile.ZipFile(zip_path, "w", zipfile.ZIP_DEFLATED) as z:
        for k, v in texts.items():
            z.writestr(k, v)
        for k, b in enumerate(blobs):
            z.writestr(f"style_sample_{k + 1:02d}.jpg", b)
    return zip_path, os.path.getsize(zip_path), len(blobs)


def natural_key(name):
    return [int(t) if t.isdigit() else t.lower() for t in re.split(r"(\d+)", str(name))]


def make_ai_images(model, category, title, story, n, s, media_dir, log, cancel=None):
    """이야기에 맞는 그림을 기획(대본 AI) → ChatGPT 또는 로컬 모델로 그려서 저장 → [{path, caption, credit, after}]"""
    local = str(s.get("fiction_image", "")).startswith("로컬")
    key = (s.get("openai_key") or os.environ.get("OPENAI_API_KEY", "")).strip()
    if local and not sd_ready():
        raise RuntimeError("로컬 그림 모델이 없습니다 (로컬그림_모델받기.bat 실행)")
    if not local and not key:
        raise RuntimeError("ChatGPT 그림에는 ChatGPT API 키가 필요합니다 (AI 엔진 탭)")
    style = image_style_text(s)
    preset = str(s.get("image_style_preset", "") or "")
    log(f"🎨 그림 {n}장 기획 중... (스타일: {preset if preset in IMAGE_STYLES else '직접 입력'})")
    cast = cast_text()
    fact_img = cat_info(category)[0] and not doc_is_fiction(str(category))   # 규칙: 사실 콘텐츠의 AI 그림은 개념도·상상도로만 (유튜브_정책.py)
    plan = ask_script_json(model, fit_ratio(IMAGE_PLAN_SYSTEM + (_YP.FACT_IMAGE_RULE if fact_img else "")), f"화면: {ratio_ko()}\n콘텐츠 종류: {category}\n그림 수: {n}장\n그림 스타일(모든 그림 공통): {style or '사실적인 영화 장면'}"
                           + (f"\n\n[등장인물 외모 - 모든 그림에서 그대로 유지, prompt 에 그대로 복사]\n{cast}" if cast else "")
                           + f"\n[제목] {title}\n\n[본문]\n{story_text_only(story)}")
    items = [x for x in (plan.get("images") or []) if isinstance(x, dict) and x.get("prompt")][:n]
    if fact_img:     # 사진처럼 보이지 않게 + 화면 설명에 'AI 상상도' (유튜브 합성 콘텐츠 표시)
        for it in items:
            it["prompt"] = str(it["prompt"]) + _YP.FACT_PROMPT_TAIL
            cap_ = str(it.get("caption", "")).strip()
            it["caption"] = cap_ if cap_.startswith(_YP.AI_CAPTION) else (f"{_YP.AI_CAPTION} · {cap_}" if cap_ else _YP.AI_CAPTION)
    if plan.get("cast"):     # 기획이 새로 정한 인물 외모를 등록(이미 있는 인물은 그대로) → 이후 모든 그림·회차에 같은 얼굴·머리·수염·체형
        have = {c.get("name") for c in IMAGE_CAST.get("chars") or []}
        new = [{"name": str(x.get("name", "")), "look": str(x.get("look", "")), "look_ko": str(x.get("look_ko", ""))}
               for x in plan["cast"] if isinstance(x, dict) and x.get("name") and x.get("look") and str(x.get("name")) not in have]
        if new:
            IMAGE_CAST["chars"] = list(IMAGE_CAST.get("chars") or []) + new
            cast = cast_text()
            log("  👤 등장인물 외모 등록:\n" + "\n".join(f"     {c['name']}: {c['look_ko'] or c['look']}" for c in new))
    if cast:   # 기획이 외모를 빠뜨려도 프로그램이 앞에 붙여 고정 (이름이 chars 에 있거나 caption/prompt 에 나오면)
        inject_cast_looks(items)
    got = []
    if local:   # 이 PC에서 무료로 (한 장 1~3분, 모델은 한 번만 올림)
        port = H > W
        w_, h_ = (448, 768) if port else (768, 432)
        log(f"  🖌 로컬 그림 {len(items)}장 그리는 중... (한 장 1~3분)")
        model_ = SD_STYLE_MODEL.get(preset, "dreamshaper")

        def has_style(p_):   # 기획이 이미 스타일 문구를 넣었으면 또 붙이지 않음 (같은 말 두 번 → 프롬프트 낭비)
            return style[:40].lower() in str(p_).lower()
        if model_ == "anime" and not sd_anime_ready():
            model_ = "dreamshaper"
        if model_ == "anime":
            neg = SD_ANIME_NEGATIVE + ", photo, realistic, 3d render"
            jobs = [{"id": f"i{k}", "prompt": "masterpiece, best quality, " + it["prompt"] + (f" {style}." if style and not has_style(it["prompt"]) else ""),
                     "negative": neg, "width": w_, "height": h_, "seed": 1000 + k} for k, it in enumerate(items)]
        else:
            neg = SD_NEGATIVE + (", " + IMAGE_STYLE_NEG[preset] if preset in IMAGE_STYLE_NEG else ", photo, realistic")
            if preset == "사실 묘사":
                neg = SD_NEGATIVE + ", " + IMAGE_STYLE_NEG["사실 묘사"]
            jobs = [{"id": f"i{k}", "prompt": it["prompt"] + (f" Style: {style}." if style and not has_style(it["prompt"]) else "") + ", highly detailed",
                     "negative": neg, "width": w_, "height": h_, "seed": 1000 + k} for k, it in enumerate(items)]
        klein = klein_ready()
        lora_, lead_ = (None, "") if klein else sd_style_lora(preset)
        if lora_:
            for j in jobs:
                j["prompt"] = lead_ + j["prompt"]
        sheets = {}
        if klein:   # 인물마다 캐릭터 시트를 먼저 그려 두고, 장면마다 나오는 인물의 시트를 기준 그림으로 → 모든 컷에서 같은 얼굴·옷
            sheets = make_cast_sheets([nm for it in items for nm in (it.get("cast_used") or [])], style, media_dir, log, cancel)
            for j, it in zip(jobs, items):
                j["refs"] = [sheets[nm] for nm in dict.fromkeys(it.get("cast_used") or []) if nm in sheets][:4]
            log("  🖌 그림 모델: FLUX.2 klein (캐릭터 시트 기준 · 인물 장면 한 장 약 2분, 풍경 약 40초)")
        else:
            log(f"  🖌 그림 모델: {'애니·만화(Counterfeit)' if model_ == 'anime' else '일러스트(Dreamshaper)'}" + (" + 수채화 보조" if lora_ else ""))
        paths = sd_generate(jobs, os.path.join(media_dir, "_sd"), log, cancel, model=model_, lora=lora_)
        # 다 그린 뒤 검증: Claude 가 직접 보고 손·얼굴·소품 결함(klein 이면 캐릭터 시트와 다른 얼굴·옷도)을 찾음 →
        # klein 이면 문제 칸만 다시 그림(부분 수정), 아니면 고칠 지시를 붙여 다른 시드로 전체를 다시 그림 → 다시 그린 것도 또 검사 (최대 3번)
        todo = [k for k in range(len(items)) if paths.get(f"i{k}")]
        fixes = {}
        base_ = {k: (jobs[k]["prompt"], int(jobs[k].get("seed", 0))) for k in range(len(jobs))}   # 고칠 지시는 원래 프롬프트에 한 번만 붙임
        for rnd in range(3):
            if not todo:
                break
            log("  🔍 그림 검증 중" + (f" ({rnd + 1}번째, 다시 그린 {len(todo)}장)" if rnd else f" ({len(todo)}장 · 손·얼굴·소품을 직접 보고)") + "...")
            res_ = check_image_defects(model, [paths[f"i{k}"] for k in todo], log, want_fix=True, want_box=klein, sheets=sheets)
            redo = [(todo[r_[0]], r_[1], (r_[2] if len(r_) > 2 else [])) for r_ in res_ if r_[0] < len(todo)]
            if not redo:
                log("  ✅ 그림 검증 통과" + (f" (다시 그린 것 포함)" if rnd else ""))
                break
            if rnd == 2:
                log(f"  ⚠ {len(redo)}장은 3번 다시 그려도 검증을 통과하지 못해 마지막 그림을 씀 (장면 편집에서 바꿀 수 있음)")
                break
            jobs2, fix2 = [], []
            for k, fx, box in redo:
                if klein and box:     # 그 칸만 다시 그림 (나머지는 그대로)
                    fix2.append({"id": f"r{rnd}_{k}", "image": paths[f"i{k}"], "out": os.path.join(media_dir, "_sd", f"r{rnd}_{k}.png"), "box": box,
                                 "prompt": "Edit the first reference image: keep the exact same picture, composition, colors and art style. Only redraw this part: "
                                           + (fx or "fix the hands so each hand has five well-formed fingers") + ". No text.",
                                 "refs": jobs[k].get("refs") or [], "seed": base_[k][1] + 777 * (rnd + 1)})
                    continue
                fixes[k] = (fixes.get(k, "") + ", " + fx).strip(", ") if fx else fixes.get(k, "")
                j = dict(jobs[k])
                hint = fixes[k] or "hands hidden, hands in pockets or behind back, focus on face and expression"
                j["prompt"] = base_[k][0] + ", " + hint
                j["seed"] = base_[k][1] + 777 * (rnd + 1)
                j["id"] = f"r{rnd}_{k}"
                jobs2.append(j)
            log(f"  🖌 다시 그리는 중: " + ", ".join(x for x in (f"{len(fix2)}장은 문제 칸만" if fix2 else "", f"{len(jobs2)}장은 전체(고칠 점 반영·다른 시드)" if jobs2 else "") if x) + "...")
            paths2 = sd_generate(jobs2, os.path.join(media_dir, "_sd"), log, cancel, model=model_, lora=lora_, fixes=fix2)
            todo = []
            for j in jobs2 + fix2:
                k = int(j["id"].split("_")[1])
                p2 = paths2.get(j["id"])
                if p2:
                    if os.path.abspath(p2) != os.path.abspath(paths.get(f"i{k}") or ""):
                        try:
                            os.remove(paths.get(f"i{k}") or "")
                        except OSError:
                            pass
                    paths[f"i{k}"] = p2
                    if "image" not in j:
                        jobs[k] = dict(jobs[k], prompt=j["prompt"], seed=j["seed"])
                    todo.append(k)
        for k, it in enumerate(items):
            p_ = paths.get(f"i{k}")
            if not p_:
                continue
            try:
                im = Image.open(p_).convert("RGB")
                im = trim_bands(im)                                            # 위아래·옆 테두리 띠 제거 (뒤에서 화면 크기로 늘림)
                if not klein:
                    im = ImageOps.autocontrast(im, cutoff=1)                   # LCM 결과는 뿌옇게 나와 대비·채도를 살림 (klein 은 그대로)
                    im = ImageEnhance.Color(im).enhance(1.25)
                    im = ImageEnhance.Contrast(im).enhance(1.08)
                up = (1080, 1920) if port else (1920, 1080)      # 영상 크기로 키움 (부드럽게)
                im = im.resize(up, Image.LANCZOS).filter(ImageFilter.UnsharpMask(radius=1.2, percent=60, threshold=2))
            except Exception:
                continue
            path = save_media_image(im, media_dir, time.strftime("aiimg_%Y%m%d_%H%M%S") + f"_{k}")
            try:   # 나중에 이 그림만 다시 그릴 수 있게 프롬프트를 옆에 저장
                atomic_write_text(path + ".prompt.json", json.dumps({"prompt": jobs[k]["prompt"], "negative": jobs[k]["negative"], "model": model_,
                                                                      "width": w_, "height": h_, "seed": jobs[k]["seed"], "caption": it.get("caption", "")}, ensure_ascii=False))
            except Exception:
                pass
            got.append({"path": path, "caption": it.get("caption", ""), "credit": "AI 생성 이미지 (로컬)", "page": "", "after": it.get("after", "")})
            try:
                os.remove(p_)
            except OSError:
                pass
        log(f"  그림 {len(got)}장 완성")
        return got
    for k, it in enumerate(items):
        if cancel is not None and cancel.is_set():
            raise RuntimeError("취소됨")
        log(f"  🎨 그림 {k + 1}/{len(items)} 그리는 중: {it.get('caption', '')}")
        prompt = it["prompt"] + (f" Style: {style}." if style else "") + fit_ratio(" Vertical 9:16 composition.") + " No text, no letters, no watermark."
        try:
            im = openai_image(prompt, key, s.get("image_model"), s.get("image_quality"))
        except APIError as e:
            if e.quota or "인증" in e.short or not got and k == 0:
                raise
            log(f"  그림 실패(건너뜀): {e.short}")
            continue
        path = save_media_image(im, media_dir, time.strftime("aiimg_%Y%m%d_%H%M%S") + f"_{k}")
        got.append({"path": path, "caption": it.get("caption", ""), "credit": "AI 생성 이미지 (ChatGPT)", "page": "",
                    "after": it.get("after", "")})
    log(f"  그림 {len(got)}장 완성")
    return got


def crop_details(full_path, details, media_dir, log, limit=3):
    """그림 전체 사진에서 details 의 상자(비율)를 잘라 확대 사진으로 저장 → [{path, caption, credit, after}]"""
    im = load_media_image(full_path)
    if im is None:
        return []
    out = []
    for d in (details or [])[:limit]:
        try:
            x, y, w, h = [float(v) for v in d.get("box", [])]
        except (TypeError, ValueError):
            continue
        x, y = min(max(x, 0), 0.95), min(max(y, 0), 0.95)
        w, h = min(max(w, 0.05), 1 - x), min(max(h, 0.05), 1 - y)
        box = (int(x * im.width), int(y * im.height), int((x + w) * im.width), int((y + h) * im.height))
        c = im.crop(box)
        if c.width < 40 or c.height < 40:
            continue
        if c.width < 900:   # 너무 작으면 키워서 또렷하게
            k = 900 / c.width
            c = c.resize((int(c.width * k), int(c.height * k)), Image.LANCZOS)
        path = save_media_image(c, media_dir)
        cap = str(d.get("caption") or "부분 확대")
        out.append({"path": path, "caption": "확대: " + cap, "credit": "원작 부분 확대", "after": d.get("after", "")})
        log(f"  확대 사진: {cap}")
    return out


def split_paras(story):
    return [x.strip() for x in re.split(r"\n\s*\n", (story or "").strip()) if x.strip()]


def _bigram_score(key, text):
    k = re.sub(r"\s+", "", key)
    t = re.sub(r"\s+", "", text)
    if len(k) < 2:
        return 0.0
    grams = {k[i:i + 2] for i in range(len(k) - 1)}
    return sum(g in t for g in grams) / len(grams)


def insert_photo_near(paras, marker, after):
    """after 와 가장 비슷한 문단 **바로 앞**에 사진 줄 삽입 (사진 → 글 순서). 못 찾으면 사진 없는 문단 중 가운데"""
    text_idx = [i for i, p in enumerate(paras) if not parse_media(p) and not PH_RE.match(p)]
    if not text_idx:
        paras.append(marker)
        return paras
    best, best_i = 0.0, None
    for i in text_idx:
        sc = _bigram_score(after, paras[i]) if after else 0
        if sc > best:
            best, best_i = sc, i
    if best >= 0.35:
        idx = best_i
    else:
        free = [i for i in text_idx if not (i >= 1 and parse_media(paras[i - 1]))]   # 앞에 사진이 없는 문단
        idx = (free or text_idx)[len(free or text_idx) // 2]
    if idx >= 1 and parse_media(paras[idx - 1]):      # 이미 그 문단 앞에 사진이 있으면 → 다음 문단 앞으로
        nxt = [i for i in text_idx if i > idx and not (i >= 1 and parse_media(paras[i - 1]))]
        idx = nxt[0] if nxt else idx
    paras.insert(idx, marker)
    return paras


def _split_inline_ph(text):
    """'문장 [사진1] 문장' → 자리표시를 별도 줄로 떼어냄"""
    pat = re.compile(r"([\[【(（]\s*(?:사진|이미지|그림|photo|image)\s*\d+\s*(?:[:：][^\]】)）]*)?[\]】)）])", re.I)
    out = []
    for line in (text or "").split("\n"):
        if parse_media(line) or PH_RE.match(line) or not pat.search(line):
            out.append(line)
            continue
        for part in pat.split(line):
            if part.strip():
                out += ["", part.strip(), ""] if PH_RE.match(part) else [part.strip()]
    return "\n".join(out)


def place_photos(story, photos):
    """본문의 [사진N] 자리표시를 실제 사진 줄로 바꾸고, 자리표시가 없는 사진은 알맞은 곳에 끼움 (최대 5장)"""
    photos = list(photos or [])[:20]
    paras = split_paras(_split_inline_ph(story))
    used = set()
    for i, p in enumerate(paras):
        m = PH_RE.match(p)
        if m:
            k = int(m.group(1)) - 1
            if 0 <= k < len(photos) and k not in used:
                ph = photos[k]
                paras[i] = make_marker(ph["path"], ph.get("caption"), ph.get("credit"), ph.get("page"))
                used.add(k)
            else:
                paras[i] = ""
    paras = [p for p in paras if p]
    rest = [k for k in range(len(photos)) if k not in used]
    rest.sort(key=lambda k: 0 if photos[k].get("after") else 1)     # 위치가 정해진 사진부터 넣고, 나머지는 빈 자리에
    for k in rest:
        ph = photos[k]
        paras = insert_photo_near(paras, make_marker(ph["path"], ph.get("caption"), ph.get("credit"), ph.get("page")), ph.get("after", ""))
    return strip_placeholders("\n\n".join(paras))


def to_placeholders(story):
    """AI에게 보낼 때 사진 줄을 [사진1] 자리표시로 바꿈 (경로 숨김)"""
    mapping, out = {}, []
    for line in (story or "").split("\n"):
        if parse_media(line):
            n = len(mapping) + 1
            mapping[n] = line.strip()
            out.append(f"[사진{n}]")
        else:
            out.append(line)
    return "\n".join(out), mapping


def from_placeholders(text, mapping):
    """AI 결과의 [사진N] 을 원래 사진 줄로 되돌림 (빠진 사진은 다시 끼움)"""
    used, out = set(), []
    for line in _split_inline_ph(text).split("\n"):
        m = PH_RE.match(line)
        if m:
            n = int(m.group(1))
            if n in mapping and n not in used:
                out.append(mapping[n])
                used.add(n)
            continue
        out.append(line)
    paras = split_paras("\n".join(out))
    for n, mk in mapping.items():
        if n not in used:
            paras = insert_photo_near(paras, mk, "")
    return strip_placeholders("\n\n".join(paras))


def story_text_only(story):
    return "\n".join(l for l in (story or "").split("\n") if not parse_media(l))


def photo_credits(story):
    res = []
    for l in (story or "").split("\n"):
        m = parse_media(l)
        if m:
            res.append(f"- {m[1] or os.path.basename(m[0])}: {m[2] or '출처 미기재'}" + (f" ({m[3]})" if m[3] else ""))
    return res


