def music_group(name):
    """음악 종류 → 분류(나라·지역)"""
    P = MUSIC_PRESETS.get(name, {})
    if P.get("gen") == "bowls":
        return "싱잉볼"
    if name in MUSIC_GROUP_KO:
        return "한국"
    for g in ("일본", "중국", "러시아", "동유럽", "중동", "아프리카"):
        if name.startswith(f"오르골 {g} ·"):
            return g
    return "서양 자장가·동요" if ("자장가" in name or "동요" in name) else "서양 민요·클래식"


