def image_depth_map(im, log=None):
    """붙여넣은 그림(PIL)의 깊이 지도(L 이미지, 밝을수록 가까움) - 깊이 AI 모델이 있을 때. 평평한 그림·모델 없음이면 None"""
    if not depth_ready() or _cv2 is None:
        return None
    im = im.convert("RGB")
    small = im.copy()
    small.thumbnail((1280, 1280))
    os.makedirs(os.path.join(BASE, "output", "media"), exist_ok=True)
    key = hashlib.md5(small.tobytes()).hexdigest()[:16]
    p = os.path.join(BASE, "output", "media", f"_bg_{key}.jpg")
    if not os.path.exists(p):
        small.save(p, quality=92)
    ensure_depth_maps([p], log)
    d = load_depth(p)
    if d is None:
        return None
    dim = Image.fromarray((d * 255).astype(np.uint8), "L").resize(im.size, Image.BILINEAR)
    return dim.filter(ImageFilter.GaussianBlur(max(1, im.width // 400)))

MUSIC_PROMPT_SYSTEM = """너는 유튜브 명상·집중·수면 음악 채널의 아트 디렉터다. 음악 종류와 제목, 사용자가 적은 분위기에 맞는 배경 이미지 프롬프트를 만든다.
- images: 3개. 서로 다른 장면(예: 자연 풍경 / 실내 공간 / 추상 빛). 각 prompt 는 영어 50~80단어: 장소·시간·빛·색감·질감·구도, 아주 고요하고 움직임이 적은 장면, 사람 없음(or 뒷모습 실루엣), 글자·워터마크 금지.
  화면 비율은 사용자가 알려준 비율. 긴 시간 봐도 피로하지 않게 대비가 부드럽고 어두운 톤 위주.
- video_prompt: 같은 장면을 5~10초짜리 '끊김 없이 반복되는(seamless loop)' 짧은 영상으로 만들 때 쓸 영어 프롬프트 1개(60~90단어). 카메라 고정 또는 아주 느린 줌, 반복 가능한 작은 움직임만(흔들리는 촛불, 떨어지는 비, 흐르는 구름, 반짝이는 별, 물결). 갑작스러운 변화 금지, 글자 금지.
- ko: 각 프롬프트의 한국어 한 줄 설명
반드시 JSON만 출력: {"images": [{"ko": "...", "prompt": "..."}], "video_prompt": "...", "video_ko": "..."}"""
MUSIC_TAIL = 12.0   # 덩어리 사이 겹치는 길이(초)


def piano_note(freq, dur=3.0, vel=0.8, soft=1.0):
    """부드러운 피아노 한 음 (배음 + 높은 배음이 먼저 사라짐)"""
    t = np.arange(int(dur * SR)) / SR
    tau = min(4.0, 1.6 * (262 / freq) ** 0.35)
    s = np.zeros_like(t)
    for k in range(1, 8):
        fk = freq * k * np.sqrt(1 + 0.0004 * k * k)
        if fk > 9000:
            break
        s += np.exp(-(k - 1) * 0.7 * soft) / k * np.sin(2 * np.pi * fk * t) * np.exp(-t * k ** 0.7 / tau)
    s *= np.minimum(1, t / 0.004) * np.clip((dur - t) / 0.3, 0, 1)
    return (s / 1.6 * vel).astype(np.float32)


def epiano_note(freq, dur=2.5, vel=0.8):
    """일렉트릭 피아노(로파이) - FM 방식"""
    t = np.arange(int(dur * SR)) / SR
    idx = 1.4 * np.exp(-t / 0.3) + 0.25
    s = np.sin(2 * np.pi * freq * t + idx * np.sin(2 * np.pi * freq * t)) * np.exp(-t / 1.3)
    s += 0.12 * np.sin(2 * np.pi * 2 * freq * t) * np.exp(-t / 0.35)
    s *= np.minimum(1, t / 0.003) * np.clip((dur - t) / 0.25, 0, 1) * (1 + 0.06 * np.sin(2 * np.pi * 4.5 * t))
    return (s * 0.55 * vel).astype(np.float32)


BOWL_MODES = ((1.0, 1.0, 16.0), (2.76, 0.5, 9.0), (5.08, 0.26, 5.0), (8.2, 0.12, 2.8), (11.8, 0.05, 1.4))   # (배음 비율, 크기, 울림 시간)


def _bowl_tone(t, freq, rng, amps=None, decay=True):
    """싱잉볼 배음들: 각 배음이 두 갈래로 살짝 어긋나 우웅우웅 맥놀이"""
    s = np.zeros_like(t)
    lb = float(np.clip((260 - freq) / 120, 0, 1))   # 낮은 볼일수록 위 배음을 키움 (작은 스피커에서도 들리게)
    for i, (ratio, amp, tau) in enumerate(BOWL_MODES):
        a = amp if amps is None else amps[i] if i < len(amps) else 0
        a *= 1 + lb * (0, 0.9, 0.8, 0.6, 0.3)[i]
        f = freq * ratio * (1 if i == 0 else rng.uniform(0.996, 1.004))
        if a <= 0 or f > 12000:
            continue
        d = rng.uniform(0.3, 1.6) * ratio ** 0.5      # 맥놀이 빠르기(Hz)
        r = rng.uniform(0.5, 0.9)
        ph = rng.uniform(0, 2 * np.pi, 2)
        tt = t
        if decay:
            tau_f = tau * (220 / freq) ** 0.3              # 작은 볼일수록 빨리 사라짐
            tt = t[:min(len(t), int(7 * tau_f * SR))]       # 거의 사라진 뒤로는 계산 생략
        part = (np.sin(2 * np.pi * f * tt + ph[0]) + r * np.sin(2 * np.pi * (f + d) * tt + ph[1])) / (1 + r)
        if decay:
            part *= np.exp(-tt / tau_f)
        s[:len(tt)] += a * part
    return s


_BOWL_CACHE = {}   # 같은 볼의 울림은 다시 계산하지 않음 (볼마다 맥놀이 성격 2가지)


def bowl_note(freq, dur=40.0, vel=0.8, rng=None):
    """싱잉볼을 나무 채로 '똑' 친 소리: 맑은 타격음 + 길게 남는 울림(수십 초)"""
    rng = rng if rng is not None else np.random.default_rng()
    key = (round(freq, 2), round(dur, 2), int(rng.integers(2)))
    if key not in _BOWL_CACHE:
        if len(_BOWL_CACHE) > 24:
            _BOWL_CACHE.clear()
        t = np.arange(int(dur * SR)) / SR
        base = _bowl_tone(t, freq, np.random.default_rng(abs(hash(key)) % 2 ** 32))
        base *= np.minimum(1, t / 0.002) * np.clip((dur - t) / 3.0, 0, 1)
        _BOWL_CACHE[key] = base.astype(np.float32)
    s = _BOWL_CACHE[key].copy()
    k = int(0.04 * SR)   # 채가 닿는 순간의 '똑'
    s[:k] += band((rng.standard_normal(k) * np.exp(-np.arange(k) / (0.006 * SR))).astype(np.float32), lo=900, hi=4500) * 0.25
    return (s * 0.5 * vel).astype(np.float32)


def bowl_rub(freq, rub=16.0, dur=40.0, vel=0.8, rng=None):
    """싱잉볼 테두리를 문질러 '노래하게' 한 소리: 천천히 커지며 웅웅 돌다가 손을 떼면 길게 사라짐"""
    rng = rng if rng is not None else np.random.default_rng()
    n = int(dur * SR)
    t = np.arange(n) / SR
    swell = 0.5 - 0.5 * np.cos(np.pi * np.minimum(1, t / 6.0))
    env = swell * np.where(t < rub, 1.0, np.exp(-(np.maximum(t - rub, 0)) / 8.0)) * np.clip((dur - t) / 3.0, 0, 1)
    rubbing = np.clip((rub - t) / 2.0, 0, 1)                       # 문지르는 동안만 1
    wob = 1 + 0.22 * rubbing * np.sin(2 * np.pi * rng.uniform(0.6, 1.1) * t + rng.uniform(0, 6.3))   # 채가 한 바퀴 돌 때마다 출렁
    grow = np.minimum(1, t / 10.0)
    tone = (_bowl_tone(t, freq, rng, amps=(1.0, 0.0, 0.1), decay=False)
            + (0.3 + 0.4 * (freq < 260)) * grow * _bowl_tone(t, freq, rng, amps=(0, 0.5), decay=False))
    fric = band(colored_noise(n, rng, 1.0), lo=freq * 0.85, hi=freq * 1.2) * 0.05 * rubbing
    s = (tone * wob + fric) * env * 0.45
    m = min(n, int(20 * SR))
    s[:m] += bowl_note(freq, 20, 0.25, rng)[:m]   # 시작할 때 살짝 치고 문지르기
    return (s * vel).astype(np.float32)


def bird_call(rng):
    """새소리 한 번 (짹짹 / 휘파람 / 떨림)"""
    kind = rng.integers(3)
    out = []
    if kind == 0:
        for _ in range(rng.integers(3, 7)):
            d = rng.uniform(0.05, 0.11)
            t = np.arange(int(d * SR)) / SR
            f0, f1 = rng.uniform(3800, 5200), rng.uniform(2600, 3600)
            ph = 2 * np.pi * np.cumsum(f0 + (f1 - f0) * t / d) / SR
            out.append(np.sin(ph) * np.sin(np.pi * t / d) ** 2)
            out.append(np.zeros(int(rng.uniform(0.05, 0.1) * SR)))
    elif kind == 1:
        for f0, f1 in ((rng.uniform(2000, 2500), rng.uniform(2700, 3200)), (rng.uniform(2600, 3000), rng.uniform(2000, 2400))):
            d = rng.uniform(0.18, 0.32)
            t = np.arange(int(d * SR)) / SR
            ph = 2 * np.pi * np.cumsum(f0 + (f1 - f0) * (t / d) ** 2) / SR
            out.append(np.sin(ph) * np.sin(np.pi * t / d))
            out.append(np.zeros(int(0.06 * SR)))
    else:
        d = rng.uniform(0.4, 0.8)
        t = np.arange(int(d * SR)) / SR
        f = rng.uniform(3800, 4800)
        out.append(np.sin(2 * np.pi * f * t) * (0.5 + 0.5 * np.sin(2 * np.pi * rng.uniform(14, 22) * t)) * np.sin(np.pi * t / d))
    return np.concatenate(out).astype(np.float32)


def _music_setup(name, seed):
    """곡 전체에서 바뀌지 않는 값(조성·빠르기 등)"""
    P = dict(MUSIC_PRESETS[name])
    rng = np.random.default_rng(seed)
    P["key"] = int(rng.integers(-3, 4))
    if P["gen"] == "lofi":
        P["bpm"] = float(rng.uniform(70, 84))
        P["bar"] = 4 * 60 / P["bpm"]
    elif P["gen"] in ("piano", "rain_piano"):
        P["bpm"] = 64.0 if P["gen"] == "piano" else 56.0
        P["bar"] = 4 * 60 / P["bpm"]
    elif P["gen"] == "jazz":
        P["bpm"] = float(rng.uniform(92, 118))
        P["bar"] = 4 * 60 / P["bpm"]
    elif P["gen"] == "bossa":
        P["bpm"] = float(rng.uniform(124, 138))
        P["bar"] = 4 * 60 / P["bpm"]
    elif P["gen"] == "lullaby":
        notes = parse_melody(P["melody"])
        beat = 60 / P["bpm"]
        P["notes"] = notes
        P["loop"] = (sum(b for _, b in notes) + 4) * beat
        P["bar"] = P["loop"]
    else:
        P["bar"] = 1.0
    return P


LOFI_PROG = [[50, 53, 57, 60, 64], [43, 53, 57, 59, 64], [48, 52, 55, 59, 62], [45, 55, 59, 60, 64]]   # ii9 V13 Imaj9 vi9
PIANO_PROG = {"warm": [[48, 55, 64, 67, 71], [53, 57, 64, 69, 72], [45, 52, 60, 64, 67], [43, 50, 59, 62, 67]],
              "sad": [[45, 52, 60, 64, 67], [41, 48, 57, 60, 65], [48, 55, 64, 67, 72], [43, 50, 59, 62, 67]]}


JAZZ_FORM = [("maj7", 0), ("7", 9), ("m7", 2), ("7", 7), ("m7", 4), ("7", 9), ("m7", 2), ("7", 7)]   # I VI ii V iii VI ii V
BOSSA_FORM = [("maj7", 0), ("maj7", 0), ("7", 2), ("7", 2), ("m7", 2), ("7", 7), ("maj7", 0), ("7", 7)]   # I II7 ii V
CHORD_TONES = {"maj7": [0, 4, 7, 11, 14], "7": [0, 4, 7, 10, 14], "m7": [0, 3, 7, 10, 14]}


def upright_bass(freq, dur=0.6, vel=0.8):
    t = np.arange(int(dur * SR)) / SR
    s = np.sin(2 * np.pi * freq * t) + 0.35 * np.sin(4 * np.pi * freq * t) * np.exp(-t / 0.12) + 0.1 * np.sin(6 * np.pi * freq * t) * np.exp(-t / 0.05)
    return (s * np.exp(-t / 0.45) * np.minimum(1, t / 0.006) * np.clip((dur - t) / 0.05, 0, 1) * vel * 0.6).astype(np.float32)


def ride_hit(rng, vel=0.5):
    t = np.arange(int(0.9 * SR)) / SR
    nz = band(rng.standard_normal(len(t)).astype(np.float32), lo=4000, hi=12000)
    ping = sum(np.sin(2 * np.pi * f * t) for f in (3150, 4720, 6380)) / 3
    return ((_norm(nz) * 0.5 + ping * 0.25) * np.exp(-t / 0.35) * np.minimum(1, t / 0.001) * vel).astype(np.float32)


def brush(rng, vel=0.3, dur=0.28):
    t = np.arange(int(dur * SR)) / SR
    nz = band(rng.standard_normal(len(t)).astype(np.float32), lo=1500, hi=7000)
    return (_norm(nz) * np.sin(np.pi * t / dur) ** 1.5 * vel).astype(np.float32)


def cafe_bed(L, rng):
    """카페 소리: 웅성거림 + 가끔 커피잔·숟가락 소리"""
    mur = []
    for _ in range(2):
        x = band(colored_noise(L, rng, 1.0), lo=250, hi=2600)
        mod = smooth_lfo(L, 0.18, rng, 0.5, 1.0) * smooth_lfo(L, 1.7, rng, 0.7, 1.0)
        mur.append(_norm(x) * mod * 0.55 + _norm(band(colored_noise(L, rng, 2.0), hi=200)) * 0.2)
    bed = np.stack(mur, 1)
    pos = rng.uniform(1, 5)
    while pos < L / SR - 2:
        f0 = rng.uniform(2400, 4200)
        clink = (bell(f0, 0.8) * 0.12 + bell(f0 * 1.47, 0.8) * 0.06).astype(np.float32)
        place(bed, clink, pos, rng.uniform(0.15, 0.85))
        pos += rng.exponential(5.0) + 1.0
    return bed


def _drum(kind, rng):
    if kind == "kick":
        t = np.arange(int(0.35 * SR)) / SR
        f = 45 + 75 * np.exp(-t / 0.04)
        return (np.sin(2 * np.pi * np.cumsum(f) / SR) * np.exp(-t / 0.18)).astype(np.float32)
    if kind == "snare":
        t = np.arange(int(0.25 * SR)) / SR
        nz = band(rng.standard_normal(len(t)).astype(np.float32), lo=1200, hi=6000)
        return (_norm(nz) * np.exp(-t / 0.07) * 0.6 + np.sin(2 * np.pi * 185 * t) * np.exp(-t / 0.05) * 0.4).astype(np.float32)
    t = np.arange(int(0.06 * SR)) / SR
    return (band(rng.standard_normal(len(t)).astype(np.float32), lo=6000) * np.exp(-t / 0.015) * 3).astype(np.float32)


def music_chunk(P, n, tail, rng, ci):
    """음악 한 덩어리 → (사건 소리, 바탕 소리) 둘 다 (n+tail, 2). 사건은 [0, n) 안에서 시작해 tail 안에서 끝남"""
    g, L = P["gen"], n + tail
    T0 = ci * n / SR
    ev = np.zeros((L, 2), np.float32)
    bed = None
    tsec = n / SR
    if g == "bowls":
        ring = tail / SR - 2                       # 한 번 친 볼이 울리는 길이 (덩어리 겹침 안에서 끝나게)
        if P.get("freqs"):                          # 432Hz·528Hz·차크라처럼 정해진 높이는 그대로
            fs = list(P["freqs"])
        else:
            fs = [midi_hz(m + P["key"]) for m in P.get("notes", (50, 52, 55, 57, 60, 62, 64, 67))]
        w = np.array(P.get("weights") or [1] * len(fs), float)
        w /= w.sum()
        low = sorted(fs)[:max(1, len(fs) // 2)]    # 문지르기는 큰(낮은) 볼로
        mode = P.get("mode", "strike")
        if mode == "chakra":                       # 뿌리→정수리 차크라 순서로 하나씩
            step = P.get("step", 12.0)
            k = int(np.ceil(T0 / step - 1e-9))
            while k * step < T0 + tsec:
                i = k % len(fs)
                place(ev, bowl_note(fs[i], ring, 0.8, rng), k * step - T0, 0.3 + 0.4 * i / max(1, len(fs) - 1))
                k += 1
        else:
            gap = P.get("gap", (8, 15))
            p_rub = {"rub": 0.6, "mix": 0.25}.get(mode, 0)
            pos = rng.uniform(0.5, 3)
            while pos < tsec:
                if rng.random() < p_rub:
                    rub = rng.uniform(12, 20)
                    place(ev, bowl_rub(rng.choice(low), rub, ring, rng.uniform(0.6, 0.85), rng), pos, rng.uniform(0.35, 0.65))
                    pos += rub + rng.uniform(4, 10)
                    continue
                place(ev, bowl_note(fs[rng.choice(len(fs), p=w)], ring, rng.uniform(0.5, 0.9), rng), pos, rng.uniform(0.25, 0.75))
                if rng.random() < 0.2 and pos + 3 < tsec:   # 가끔 다른 볼을 이어서 한 번 더
                    place(ev, bowl_note(rng.choice(fs), ring, rng.uniform(0.35, 0.6), rng), pos + rng.uniform(1.5, 3), rng.uniform(0.25, 0.75))
                pos += rng.uniform(*gap)
        ev = reverb(ev, rng, 3.5, 0.3)
        bed = np.stack([_norm(band(colored_noise(L, rng, 1.0), lo=120, hi=1500)) for _ in range(2)], 1) * 0.012   # 아주 작은 방 공기 소리
    elif g == "sleep":
        bed = gen_pad(L, rng, "warm", 14, 900) * 0.8 + np.stack([_norm(band(colored_noise(L, rng, 2.0), hi=300)) for _ in range(2)], 1) * 0.12
        pos = rng.uniform(2, 6)
        while pos < tsec:
            m = rng.choice([60, 64, 67, 69, 72]) + P["key"]
            place(ev, piano_note(midi_hz(m), 6, rng.uniform(0.15, 0.3), 1.6), pos, rng.uniform(0.3, 0.7))
            pos += rng.uniform(6, 13)
        ev = reverb(ev, rng, 4.0, 0.5)
    elif g == "lofi":
        beat = 60 / P["bpm"]
        bars = int(round(tsec / P["bar"]))
        sw = 0.58
        kick, snare = _drum("kick", rng), _drum("snare", rng)
        mel = np.zeros((L, 2), np.float32)
        drums = np.zeros((L, 2), np.float32)
        for b in range(bars):
            bt = b * P["bar"]
            gb = ci * bars + b
            ch = [m + P["key"] for m in LOFI_PROG[gb % 4]]
            for j, m in enumerate(ch):
                place(mel, epiano_note(midi_hz(m), P["bar"] * 0.95, rng.uniform(0.45, 0.6)), bt + j * 0.012, 0.35 + 0.075 * j)
            if rng.random() < 0.5:
                for j, m in enumerate(ch[1:]):
                    place(mel, epiano_note(midi_hz(m), beat * 1.5, 0.28), bt + 2.5 * beat + j * 0.01, 0.4 + 0.07 * j)
            root = midi_hz(ch[0] - 12)
            for bb in (0, 2.5):
                tt = np.arange(int(beat * 1.4 * SR)) / SR
                bass = (np.sin(2 * np.pi * root * tt) * np.exp(-tt / 0.6) * np.minimum(1, tt / 0.01)).astype(np.float32)
                place(mel, bass * 0.5, bt + bb * beat, 0.5)
            if rng.random() < 0.35:   # 짧은 피아노 멜로디
                scale = [ch[0] + 24 + x for x in (0, 2, 4, 7, 9, 12)]
                tt = bt + rng.choice([1, 2]) * beat
                for _ in range(rng.integers(3, 6)):
                    place(mel, piano_note(midi_hz(rng.choice(scale)), 1.8, rng.uniform(0.18, 0.3)), tt, rng.uniform(0.4, 0.7))
                    tt += rng.choice([0.5, 0.5, 1]) * beat
            for k in (0, 2.5):
                place(drums, kick * 0.9, bt + k * beat, 0.5)
            if rng.random() < 0.3:
                place(drums, kick * 0.5, bt + 1.75 * beat, 0.5)
            for k in (1, 3):
                place(drums, snare * 0.45, bt + k * beat + rng.uniform(0, 0.012), 0.5)
            for e in range(8):
                if rng.random() < 0.9:
                    off = (e // 2) * beat + (sw * beat if e % 2 else 0)
                    place(drums, _drum("hat", rng) * rng.uniform(0.12, 0.22), bt + off, 0.62)
        mel = reverb(mel, rng, 1.8, 0.22)
        ev = np.stack([band(mel[:, c], hi=6500) for c in range(2)], 1) * 0.9 + np.stack([band(drums[:, c], hi=8000) for c in range(2)], 1) * 0.7
        crk = np.zeros(L, np.float32)
        k = int(L / SR * 6)
        crk[rng.integers(0, L, k)] = rng.uniform(0.2, 1, k)
        vinyl = band(crk + colored_noise(L, rng, 1.0) * 0.02, lo=800, hi=5000)
        bed = np.stack([vinyl, vinyl], 1) * 0.08
    elif g in ("piano", "rain_piano"):
        beat = 60 / P["bpm"]
        prog = PIANO_PROG["warm" if g == "piano" else "sad"]
        bars = int(round(tsec / P["bar"]))
        for b in range(bars):
            bt = b * P["bar"]
            gb = ci * bars + b
            ch = [m + P["key"] for m in prog[(gb // 2) % 4]]
            place(ev, piano_note(midi_hz(ch[0] - 12), P["bar"] * 1.6, 0.45), bt, 0.45)
            dens = 0.75 if g == "piano" else 0.5
            for e in range(8):
                if rng.random() < dens:
                    m = ch[1:][e % 4] + (12 if rng.random() < 0.2 else 0)
                    place(ev, piano_note(midi_hz(m), 3.0, rng.uniform(0.25, 0.42)), bt + e * beat / 2 + rng.uniform(0, 0.015), rng.uniform(0.3, 0.7))
        ev = reverb(ev, rng, 3.2, 0.38)
        if g == "rain_piano":
            bed = gen_rain(L, rng) * 0.42
    elif g == "rain":
        bed = gen_rain(L, rng)
        if rng.random() < 0.35:   # 먼 천둥
            d = 6.0
            tt = np.arange(int(d * SR)) / SR
            th = band(colored_noise(len(tt), rng, 2.0), hi=180) * np.minimum(1, tt / 0.6) * np.exp(-tt / 2.2)
            place(ev, (_norm(th) * 0.5).astype(np.float32), rng.uniform(5, max(6, tsec - 8)), rng.uniform(0.3, 0.7))
    elif g == "roof":
        # 바탕: 멀리 쏟아지는 비 (부드럽게)
        bed = gen_rain(L, rng) * 0.45
        # 지붕에 맞는 빗방울: 톡·탁 (울림 있는 짧은 소리)
        drops = np.zeros((L, 2), np.float32)
        rate = 9.0 * (0.75 + 0.5 * smooth_lfo(n, 20, rng))     # 초당 빗방울 수가 천천히 바뀜
        cnt = int(n / SR * 9)
        pos = np.sort(rng.uniform(0, n / SR, cnt))
        keep = rng.random(cnt) < rate[np.minimum((pos * SR).astype(int), n - 1)] / 13.5
        kinds = []
        for f0 in (650, 900, 1250, 1800, 2400):    # 기와·양철에 따라 다른 높이
            tt = np.arange(int(0.05 * SR)) / SR
            kinds.append((np.sin(2 * np.pi * f0 * tt) * np.exp(-tt / 0.008) + rng.standard_normal(len(tt)) * np.exp(-tt / 0.002) * 0.6).astype(np.float32))
        for ps in pos[keep]:
            k = kinds[int(rng.integers(len(kinds)))] * rng.uniform(0.15, 0.6)
            place(drops, k, ps, rng.uniform(0.1, 0.9))
        drops = np.stack([band(drops[:, c], lo=400, hi=6000) for c in range(2)], 1)
        # 처마 끝 낙숫물: 일정한 간격으로 똑… 똑
        drip = np.zeros((L, 2), np.float32)
        for side in (0.25, 0.75):
            t_ = rng.uniform(0, 1.0)
            per = rng.uniform(0.6, 1.4)
            while t_ < n / SR:
                tt = np.arange(int(0.12 * SR)) / SR
                f = rng.uniform(1100, 1500) * (1 + 0.6 * np.exp(-tt / 0.01))
                d_ = (np.sin(2 * np.pi * np.cumsum(f) / SR) * np.exp(-tt / 0.03) * rng.uniform(0.2, 0.35)).astype(np.float32)
                place(drip, d_, t_, side)
                t_ += per * rng.uniform(0.85, 1.15)
        ev = reverb(drops * 0.9 + drip, rng, 1.2, 0.25)
    elif g == "waves":
        bed = gen_waves(L, rng)
    elif g == "forest":
        lfo = smooth_lfo(L, 0.4, rng, 0.6, 1.0)
        bed = np.stack([_norm(band(colored_noise(L, rng, 1.0), lo=300, hi=3000)) * lfo * 0.35
                        + _norm(band(colored_noise(L, rng, 2.0), hi=250)) * 0.15 for _ in range(2)], 1)
        pos = rng.uniform(0.5, 2)
        while pos < tsec:
            c = bird_call(rng)
            dist = rng.uniform(0.25, 1.0)
            if dist < 0.5:
                c = band(c, hi=3500)
            place(ev, c * 0.35 * dist, pos, rng.uniform(0.1, 0.9))
            pos += rng.uniform(1.2, 5.5)
        ev = reverb(ev, rng, 1.8, 0.3)
    elif g == "fire":
        bed = np.stack([_norm(band(colored_noise(L, rng, 2.0), hi=300)) * (0.7 + 0.3 * smooth_lfo(L, 1.5, rng)) * 0.6
                        + _norm(band(colored_noise(L, rng, 1.0), lo=900, hi=4000)) * 0.08 for _ in range(2)], 1)
        imp = np.zeros((L, 2), np.float32)
        pos = 0.0
        while pos < tsec:
            burst = rng.integers(1, 6)
            for _ in range(burst):
                i = int((pos + rng.uniform(0, 0.25)) * SR)
                if i < n:
                    p_ = rng.uniform(0.2, 0.8)
                    a = rng.uniform(0.3, 1.0) * (1.8 if rng.random() < 0.06 else 1)
                    imp[i, 0] += a * (1 - p_)
                    imp[i, 1] += a * p_
            pos += rng.exponential(0.5)
        kl = int(0.012 * SR)
        kern = (rng.standard_normal(kl) * np.exp(-np.arange(kl) / (0.002 * SR))).astype(np.float32)
        ev = np.stack([band(ola_conv(imp[:, c], kern), lo=1200, hi=7000) for c in range(2)], 1) * 0.6
    elif g == "brown":
        bed = np.stack([_norm(band(colored_noise(L, rng, 2.0), hi=500)) * (0.92 + 0.08 * smooth_lfo(L, 6, rng)) for _ in range(2)], 1)
    elif g == "binaural":
        t = (np.arange(L) / SR + T0)       # 전체 시간 기준 → 덩어리가 바뀌어도 위상이 이어짐
        fc, fb = P["carrier"], P["beat"]
        tone = np.stack([np.sin(2 * np.pi * fc * t), np.sin(2 * np.pi * (fc + fb) * t)], 1).astype(np.float32) * 0.3
        bed = tone + gen_pad(L, rng, "space", 14, 800) * 0.35 + np.stack([_norm(band(colored_noise(L, rng, 1.0), hi=1200)) for _ in range(2)], 1) * 0.05
    elif g == "jazz":
        beat = 60 / P["bpm"]
        sw = 0.66          # 스윙 (셋잇단 느낌)
        bars = int(round(tsec / P["bar"]))
        root0 = 48 + P["key"]
        bass, piano, drums = (np.zeros((L, 2), np.float32) for _ in range(3))
        for b in range(bars):
            bt = b * P["bar"]
            gb = ci * bars + b
            q, r_ = JAZZ_FORM[gb % 8]
            nq, nr = JAZZ_FORM[(gb + 1) % 8]
            root = root0 - 12 + r_
            tones = CHORD_TONES[q]
            nxt = root0 - 12 + nr
            walk = [root, root + rng.choice(tones[1:3]), root + rng.choice([7, 12, tones[1]]), nxt + rng.choice([-1, 1, 2])]
            for k, m in enumerate(walk):
                place(bass, upright_bass(midi_hz(m), beat * 0.95, 0.85 if k == 0 else 0.7), bt + k * beat + rng.uniform(0, 0.01), 0.45)
            for k in range(4):   # 라이드 심벌 '칭 칭-가 칭 칭-가'
                place(drums, ride_hit(rng, 0.32 if k % 2 == 0 else 0.4), bt + k * beat, 0.62)
                if k % 2 == 1:
                    place(drums, ride_hit(rng, 0.22), bt + k * beat + sw * beat, 0.62)
                    place(drums, brush(rng, 0.22), bt + k * beat, 0.45)
            voic = [root0 + r_ + tones[1], root0 + r_ + tones[3], root0 + r_ + tones[4]]   # 루트 없는 보이싱(3·7·9)
            for hit in ([1 + sw] if rng.random() < 0.6 else [0]) + ([3] if rng.random() < 0.5 else []):
                for j, m in enumerate(voic):
                    place(piano, piano_note(midi_hz(m), beat * 1.6, rng.uniform(0.18, 0.26)), bt + hit * beat + j * 0.008, 0.4 + 0.08 * j)
            if (gb // 2) % 2 == 1 and rng.random() < 0.85:   # 2마디씩 즉흥 멜로디
                scale = [root0 + 12 + r_ + x for x in tones] + [root0 + 24 + r_ + tones[0]]
                tt, idx = bt, int(rng.integers(len(scale)))
                while tt < bt + P["bar"] - 0.1:
                    if rng.random() < 0.8:
                        place(piano, piano_note(midi_hz(scale[idx]), 1.0, rng.uniform(0.22, 0.32), 1.3), tt, 0.55)
                    idx = int(np.clip(idx + rng.choice([-2, -1, 1, 1, 2]), 0, len(scale) - 1))
                    step = sw * beat if ((tt - bt) / beat) % 1 < 0.1 else (1 - sw) * beat
                    tt += step if rng.random() < 0.75 else beat
        ev = reverb(piano, rng, 1.6, 0.25) + reverb(bass, rng, 1.0, 0.12) * 1.1 + reverb(drums, rng, 1.4, 0.2) * 0.8
        ev = np.stack([band(ev[:, c], hi=9000) for c in range(2)], 1)
        if P.get("cafe"):
            bed = cafe_bed(L, rng) * 0.55
    elif g == "bossa":
        beat = 60 / P["bpm"]
        bars = int(round(tsec / P["bar"]))
        root0 = 48 + P["key"]
        gtr, perc, mel = (np.zeros((L, 2), np.float32) for _ in range(3))
        shaker = brush(rng, 0.12, 0.08)
        for b in range(bars):
            bt = b * P["bar"]
            gb = ci * bars + b
            q, r_ = BOSSA_FORM[gb % 8]
            tones = CHORD_TONES[q]
            root = root0 - 12 + r_
            for k, m in ((0, root), (1.5, root + 7), (2, root), (3.5, root + 7)):   # 엄지 베이스
                place(gtr, pluck(midi_hz(m), 1.0) * 0.6, bt + k * beat, 0.45)
            ch = [root0 + r_ + x for x in (tones[1], tones[2], tones[3], tones[4])]
            for e in ((0, 1.5, 2.5) if gb % 2 == 0 else (0.5, 1.5, 3)):   # 보사노바 손가락 리듬
                for j, m in enumerate(ch):
                    place(gtr, pluck(midi_hz(m), 0.9) * 0.28, bt + e * beat + j * 0.006, 0.55)
            for e in range(8):
                place(perc, shaker * (1.2 if e % 2 else 0.8), bt + e * beat / 2, 0.68)
            for k in ((0, 1.5, 3) if gb % 2 == 0 else (1, 2.5)):   # 림 클릭(클라베)
                tt_ = np.arange(int(0.05 * SR)) / SR
                place(perc, (np.sin(2 * np.pi * 1700 * tt_) * np.exp(-tt_ / 0.01) * 0.25).astype(np.float32), bt + k * beat, 0.4)
            if (gb // 4) % 2 == 1 and rng.random() < 0.8:
                scale = [root0 + 12 + r_ + x for x in (0, 2, 4, 7, 9, 12)]
                tt = bt + rng.choice([0, 0.5]) * beat
                while tt < bt + P["bar"] - 0.2:
                    place(mel, piano_note(midi_hz(rng.choice(scale)), 1.4, rng.uniform(0.2, 0.3), 1.2), tt, 0.5)
                    tt += rng.choice([0.5, 1, 1, 1.5]) * beat
        ev = reverb(gtr, rng, 1.4, 0.18) + reverb(mel, rng, 2.0, 0.3) + perc * 0.8
        ev = np.stack([band(ev[:, c], hi=10000) for c in range(2)], 1)
    elif g == "lullaby":
        beat = 60 / P["bpm"]
        loop = P["loop"]
        PROGS["_lull"] = [[m + P["key"] for m in ch] for ch in _melody_chords(P["notes"], P.get("minor", False), P.get("tonic"), P.get("scale"))]   # 멜로디와 같은 조로
        bed = gen_pad(L, rng, "_lull", 8 * beat, 1300) * 0.3
        k0 = int(T0 // loop)
        cache = {}
        for k in range(k0, k0 + int(tsec // loop) + 2):
            t = k * loop + beat
            for midi, b in P["notes"]:
                if midi is not None and T0 <= t < T0 + tsec:
                    m = midi + 12 + P["key"]
                    if m not in cache:
                        cache[m] = pluck(midi_hz(m), 2.2)
                    place(ev, cache[m] * rng.uniform(0.6, 0.85), t - T0, 0.5 + 0.2 * np.sin(t))
                t += b * beat
        ev = reverb(ev, rng, 2.8, 0.35)
    elif g == "space":
        bed = gen_space(L, rng)
    return ev, bed


def load_audio_file(path):
    """MP3·WAV·M4A 등 음악 파일 → (n, 2) float32 (44.1kHz 스테레오, ffmpeg로 풀기)"""
    p = subprocess.run([get_ffmpeg(), "-v", "error", "-i", path, "-f", "f32le", "-ac", "2", "-ar", str(SR), "-"],
                       stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                       creationflags=(subprocess.CREATE_NO_WINDOW if os.name == "nt" else 0))
    if p.returncode != 0 or not p.stdout:
        raise RuntimeError("음악 파일을 읽지 못했습니다: " + p.stderr.decode("utf-8", "replace")[-300:])
    a = np.frombuffer(p.stdout, np.float32).reshape(-1, 2)
    loud = np.where(np.abs(a).max(1) > 10 ** (-50 / 20))[0]     # 앞뒤 무음(-50dB 이하) 잘라내기
    if len(loud) == 0:
        raise RuntimeError("음악 파일에 소리가 없습니다.")
    return a[loud[0]:loud[-1] + 1]


def render_audio_loop(src, minutes, wav_path, xfade=3.0, start=0.0, progress=None, cancel=None, audio=None):
    """음악 파일을 minutes 분 길이로 되풀이해 WAV로 저장. 이음매는 xfade 초 겹쳐 부드럽게. 반환: 길이(초)
    start: 이 초부터 저장 (이음매 미리듣기용)"""
    import wave
    a = load_audio_file(src) if audio is None else audio
    M = len(a)
    X = int(min(xfade, M / SR / 4) * SR)
    if X > 0:
        w_ = np.sin(np.linspace(0, np.pi / 2, X, dtype=np.float32)) ** 2
        joint = a[M - X:] * (1 - w_)[:, None] + a[:X] * w_[:, None]   # 끝과 처음을 겹친 이음매
    total = int(max(0.1, float(minutes)) * 60 * SR)
    skip = int(start * SR)
    fade_in, fade_out = int(0.5 * SR), int(min(8, total / SR / 4) * SR)
    os.makedirs(os.path.dirname(os.path.abspath(wav_path)), exist_ok=True)
    pos, rep = 0, 0
    est = max(1, int(np.ceil(total / max(1, M - X))))
    with wave.open(wav_path, "wb") as w:
        w.setnchannels(2)
        w.setsampwidth(2)
        w.setframerate(SR)
        while pos < total:
            if cancel is not None and cancel.is_set():
                raise RuntimeError("취소됨")
            seg = a[:M - X] if rep == 0 else np.concatenate([joint, a[X:M - X]]) if X else a
            seg = seg[:total - pos]
            idx = np.arange(pos, pos + len(seg))
            env = np.minimum(1, idx / fade_in) * np.clip((total - idx) / fade_out, 0, 1)
            out = seg * env[:, None]
            if pos + len(seg) > skip:
                k = max(0, skip - pos)
                w.writeframes((np.clip(out[k:], -1, 1) * 32767).astype("<i2").tobytes())
            pos += len(seg)
            rep += 1
            if progress:
                progress(min(rep, est), est)
    return (total - min(skip, total)) / SR


# ---------------- 📊 PPT 발표 영상 (슬라이드 → AI 나레이션 → 영상) ----------------
PPT_EXPORT_PS1 = r'''param([string]$Src, [string]$Out, [int]$Bold = 1, [int]$Only = 0)
$ErrorActionPreference = "Stop"
$thin = "Light|Thin|Semilight|SemiLight|Hairline|ExtraLight|UltraLight|얇은"
function Fix-Text($tr) {
  try {
    $n = $tr.Runs().Count
    for ($k = 1; $k -le $n; $k++) {
      $r = $tr.Runs($k)
      try { $r.Font.Bold = -1 } catch {}
      try { if ($r.Font.Name -match $thin) { $r.Font.Name = "맑은 고딕" } } catch {}
      try { if ($r.Font.NameFarEast -match $thin) { $r.Font.NameFarEast = "맑은 고딕" } } catch {}
    }
  } catch {}
}
function Fix-Shape($sh) {
  try { if ($sh.Type -eq 6) { foreach ($g in $sh.GroupItems) { Fix-Shape $g }; return } } catch {}
  try { if ($sh.HasTextFrame -and $sh.TextFrame.HasText) { Fix-Text $sh.TextFrame.TextRange } } catch {}
  try {
    if ($sh.HasTable) {
      $t = $sh.Table
      for ($a = 1; $a -le $t.Rows.Count; $a++) { for ($b = 1; $b -le $t.Columns.Count; $b++) { Fix-Text $t.Cell($a, $b).Shape.TextFrame.TextRange } }
    }
  } catch {}
}
$pp = $null; $started = $false
for ($try = 0; $try -lt 8 -and -not $pp; $try++) {       # 켜져 있는 PowerPoint 에 붙음 (바쁘면 잠시 기다렸다 다시)
  try { $cand = [Runtime.InteropServices.Marshal]::GetActiveObject("PowerPoint.Application"); $null = $cand.Presentations.Count; $pp = $cand }
  catch { if ($_.Exception.HResult -eq -2147221021) { break }; Start-Sleep -Milliseconds 800 }
}
if (-not $pp) { $pp = New-Object -ComObject PowerPoint.Application; $started = $true }
$pres = $null
try {
  for ($try = 0; $try -lt 8 -and -not $pres; $try++) {
    try { $pres = $pp.Presentations.Open($Src, -1, 0, 0) }   # $Src 는 프로그램이 만든 복사본 (사용자가 열어 둔 원본은 건드리지 않음)
    catch { if ($try -ge 7) { throw }; Start-Sleep -Milliseconds 800 }
  }
  $w = 1920
  $h = [int](1920 * $pres.PageSetup.SlideHeight / $pres.PageSetup.SlideWidth)
  $list = @()
  $from = 1; $to = $pres.Slides.Count
  if ($Only -ge 1 -and $Only -le $pres.Slides.Count) { $from = $Only; $to = $Only }     # 한 장만 다시
  for ($i = $from; $i -le $to; $i++) {
    $s = $pres.Slides.Item($i)
    if ($Bold) { foreach ($sh in $s.Shapes) { Fix-Shape $sh } }      # 화면용 그림에만 적용 (원본 파일은 저장 안 함)
    # 클릭 애니메이션: 클릭 전 단계마다 그림 (마지막 = 모든 클릭 후 = slide_NNN.png)
    $steps = @(); $reveal = @()
    $seq = $s.TimeLine.MainSequence
    if ($seq.Count -gt 0) {
      $eff = @(); $g = 0
      for ($k = 1; $k -le $seq.Count; $k++) {
        $e = $seq.Item($k)
        if ($e.Timing.TriggerType -eq 1) { $g++ }
        $et = [int]$e.EffectType
        if (-not $e.Exit -and $et -ge 54 -and $et -le 72) { continue }       # 강조 효과는 보임/숨김과 상관없음
        $eff += [pscustomobject]@{ sh = $e.Shape; g = $g; ex = [bool]$e.Exit }
      }
      if ($g -gt 0 -and $eff.Count -gt 0) {
        $names = @($eff | ForEach-Object { $_.sh.Name })
        $extra = @()
        foreach ($x in $eff) {                                                # 움직이는 도형 안에 든 글상자도 같이
          foreach ($o in $s.Shapes) {
            if ($names -contains $o.Name) { continue }
            if ($o.Left -ge $x.sh.Left - 2 -and $o.Top -ge $x.sh.Top - 2 -and ($o.Left + $o.Width) -le ($x.sh.Left + $x.sh.Width + 2) -and ($o.Top + $o.Height) -le ($x.sh.Top + $x.sh.Height + 2)) {
              $extra += [pscustomobject]@{ sh = $o; g = $x.g; ex = $x.ex }; $names += $o.Name
            }
          }
        }
        $eff += $extra
        for ($c = 1; $c -le $g; $c++) {
          $t = @()
          foreach ($x in $eff) { if ($x.g -eq $c) { try { if ($x.sh.HasTextFrame -and $x.sh.TextFrame.HasText) { $t += $x.sh.TextFrame.TextRange.Text } } catch {} } }
          $reveal += (($t -join " / ") -replace "\s+", " ")
        }
        for ($c = 0; $c -lt $g; $c++) {
          foreach ($x in $eff) { $x.sh.Visible = $(if ($x.ex) { -1 } else { 0 }) }
          foreach ($x in $eff) { if ($x.g -le $c) { $x.sh.Visible = $(if ($x.ex) { 0 } else { -1 }) } }
          $p = Join-Path $Out ("slide_{0:D3}_{1}.png" -f $i, $c)
          $s.Export($p, "PNG", $w, $h); $steps += $p
        }
        foreach ($x in $eff) { $x.sh.Visible = -1 }
      }
    }
    $img = Join-Path $Out ("slide_{0:D3}.png" -f $i)
    $s.Export($img, "PNG", $w, $h)
    $texts = @()
    foreach ($sh in $s.Shapes) { try { if ($sh.HasTextFrame -and $sh.TextFrame.HasText) { $texts += $sh.TextFrame.TextRange.Text } } catch {} }
    $notes = ""
    try { foreach ($sh in $s.NotesPage.Shapes) { try { if ($sh.PlaceholderFormat.Type -eq 2 -and $sh.TextFrame.HasText) { $notes = $sh.TextFrame.TextRange.Text } } catch {} } } catch {}
    $hi = ""
    $hasPic = $false
    foreach ($sh in $s.Shapes) { try { if ($sh.Type -eq 13 -or $sh.Type -eq 11) { $hasPic = $true } } catch {} }
    if ($hasPic) { $hi = Join-Path $Out ("slide_{0:D3}_hi.png" -f $i); $s.Export($hi, "PNG", 2560, [int](2560 * $h / $w)) }   # 확대용
    $list += [pscustomobject]@{ n = $i; image = $img; text = ($texts -join "`n"); notes = $notes; steps = @($steps); reveal = @($reveal); hires = $hi }
  }
  $jsName = $(if ($Only -ge 1) { "slide_{0:D3}.json" -f $Only } else { "slides.json" })
  ConvertTo-Json -InputObject @($list) -Depth 3 | Out-File -Encoding utf8 (Join-Path $Out $jsName)
} finally {
  if ($pres) { try { $pres.Saved = -1; $pres.Close() } catch {} }
  if ($started) { try { $pp.Quit() } catch {} }        # 사용자가 쓰고 있던 PowerPoint 는 그대로 둠
}
'''


def ppt_export(src, out_dir, log=None, bold=True, only=0):
    """PPT/PPTX → 슬라이드 그림(1920px PNG) + 슬라이드 글 + 발표자 메모. PowerPoint(설치되어 있어야 함)를 직접 조종.
    반환: [{"n", "image", "text", "notes"}].  only=N: N번 슬라이드 한 장만 다시 (다른 장 파일은 그대로)"""
    log = log or (lambda x: None)
    os.makedirs(out_dir, exist_ok=True)
    for f_ in os.listdir(out_dir):
        if only:
            if f_.startswith(f"slide_{only:03d}"):
                os.remove(os.path.join(out_dir, f_))
        elif f_.startswith("slide_") or f_ == "slides.json":
            os.remove(os.path.join(out_dir, f_))
    ps1 = os.path.join(out_dir, "_export.ps1")
    with open(ps1, "w", encoding="utf-8-sig") as f:       # BOM: 윈도우 PowerShell 이 한글 경로를 바르게 읽게
        f.write(PPT_EXPORT_PS1)
    log((f"📊 PowerPoint로 {only}번 슬라이드만 다시 그림으로 바꾸는 중..." if only else "📊 PowerPoint로 슬라이드를 그림으로 바꾸는 중...") + (" (글자 굵게)" if bold else ""))
    copy = os.path.join(out_dir, "_src" + os.path.splitext(src)[1])     # 복사본으로 작업: PowerPoint 에 열려 있는 원본과 부딪히지 않게
    shutil.copy2(src, copy)
    try:
        p = subprocess.run(["powershell", "-NoProfile", "-ExecutionPolicy", "Bypass", "-File", ps1, "-Src", os.path.abspath(copy), "-Out", os.path.abspath(out_dir),
                            "-Bold", "1" if bold else "0", "-Only", str(int(only or 0))],
                           capture_output=True, text=True, encoding="utf-8", errors="replace", timeout=900,
                           creationflags=(subprocess.CREATE_NO_WINDOW if os.name == "nt" else 0))
    finally:
        try:
            os.remove(copy)
        except OSError:
            pass
    js = os.path.join(out_dir, f"slide_{only:03d}.json" if only else "slides.json")
    if p.returncode != 0 or not os.path.exists(js):
        raise RuntimeError("슬라이드를 바꾸지 못했습니다. PowerPoint가 설치되어 있는지 확인하세요.\n" + (p.stderr or p.stdout)[-400:])
    if not only:
        try:
            atomic_write_text(os.path.join(out_dir, "_export_meta.json"),
                              json.dumps({"src": os.path.abspath(src), "mtime": os.path.getmtime(src), "size": os.path.getsize(src), "bold": bool(bold)}))
        except Exception:
            pass
    return ppt_parse_slides(js)


def ppt_parse_slides(js):
    data = json.load(open(js, encoding="utf-8-sig"))
    data = data if isinstance(data, list) else [data]
    clean = lambda t: re.sub(r"[ \t]+", " ", str(t or "").replace("\r", "\n").replace("\x0b", "\n")).strip()
    lst_ = lambda v: [x for x in (v if isinstance(v, list) else [v]) if x] if v else []
    return [{"n": int(d["n"]), "image": d["image"], "text": clean(d.get("text")), "notes": clean(d.get("notes")),
             "steps": lst_(d.get("steps")), "reveal": [clean(x) for x in lst_(d.get("reveal"))], "hires": d.get("hires") or ""} for d in data]


def ppt_export_cached(src, out_dir, log=None, bold=True):
    """전에 바꿔 둔 그림이 있고 PPT 파일이 그 뒤로 안 바뀌었으면 PowerPoint 를 거치지 않고 바로 씀 (몇 초)"""
    log = log or (lambda x: None)
    meta_p, js = os.path.join(out_dir, "_export_meta.json"), os.path.join(out_dir, "slides.json")
    try:
        meta = json.load(open(meta_p, encoding="utf-8"))
        same = (os.path.normcase(meta.get("src", "")) == os.path.normcase(os.path.abspath(src)) and abs(float(meta.get("mtime", 0)) - os.path.getmtime(src)) < 1
                and int(meta.get("size", -1)) == os.path.getsize(src) and bool(meta.get("bold", True)) == bool(bold) and os.path.exists(js))
        if same:
            sl = ppt_parse_slides(js)
            if sl and all(os.path.exists(x["image"]) for x in sl):
                log(f"📊 PPT 파일이 그대로라 전에 바꿔 둔 슬라이드 그림 {len(sl)}장을 바로 씁니다 (PowerPoint 생략)")
                return sl
    except Exception:
        pass
    return ppt_export(src, out_dir, log, bold)


