def media_duration(path):
    """영상 길이(초) - ffmpeg 정보에서 읽음"""
    p = subprocess.run([get_ffmpeg(), "-i", path], stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, errors="replace",
                       creationflags=(subprocess.CREATE_NO_WINDOW if os.name == "nt" else 0))
    m = re.search(r"Duration:\s*(\d+):(\d+):(\d+(?:\.\d+)?)", p.stderr or "")
    if not m:
        raise RuntimeError("영상 길이를 읽지 못했습니다: " + os.path.basename(path))
    return int(m.group(1)) * 3600 + int(m.group(2)) * 60 + float(m.group(3))


def media_size(path):
    p = subprocess.run([get_ffmpeg(), "-i", path], stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, errors="replace",
                       creationflags=(subprocess.CREATE_NO_WINDOW if os.name == "nt" else 0))
    m = re.search(r"Video:.*?(\d{3,5})x(\d{3,5})", p.stderr or "")
    return (int(m.group(1)), int(m.group(2))) if m else (1920, 1080)


def shorts_overlay(top, bottom, s, path):
    """쇼츠 위·아래 글자 (1080×1920 투명 PNG)"""
    layer = Image.new("RGBA", (1080, 1920), (0, 0, 0, 0))
    d = ImageDraw.Draw(layer)
    fp = s.get("title_font_path") or s.get("font_path")
    if top.strip():
        size = 92
        f = load_font(fp, size)
        lines = wrap(top.strip(), f, 960)
        while len(lines) > 3 and size > 50:
            size -= 6
            f = load_font(fp, size)
            lines = wrap(top.strip(), f, 960)
        y = 260 - (len(lines) - 1) * size * 0.6
        for ln in lines:
            x = (1080 - f.getlength(ln)) / 2
            d.text((x, y), ln, font=f, fill="#FFFFFF", stroke_width=max(5, size // 12), stroke_fill="#000000")
            y += size * 1.2
    if bottom.strip():
        f2 = load_font(s.get("font_path") or fp, 50)
        for i, ln in enumerate(wrap(bottom.strip(), f2, 960)[:2]):
            x = (1080 - f2.getlength(ln)) / 2
            d.text((x, 1560 + i * 64), ln, font=f2, fill="#FFE135", stroke_width=4, stroke_fill="#000000")
    layer.save(path)


def cut_short(src, out, start, length, top, bottom, s, mode="가운데"):
    """롱폼 영상의 한 구간 → 세로 쇼츠 (가운데 맞춤 + 흐린 배경, 또는 꽉 채우기) + 위·아래 글자 + 소리 페이드"""
    png = out + ".ov.png"
    shorts_overlay(top, bottom, s, png)
    w, h = media_size(src)
    if h >= w:   # 이미 세로 영상
        base = "[0:v]scale=1080:1920:force_original_aspect_ratio=increase,crop=1080:1920,setsar=1[v1]"
    elif mode.startswith("꽉"):
        base = "[0:v]scale=-2:1920,crop=1080:1920,setsar=1[v1]"
    else:
        base = ("[0:v]split=2[a][b];[a]scale=1080:1920:force_original_aspect_ratio=increase,crop=1080:1920,boxblur=24:2,eq=brightness=-0.12[bg];"
                "[b]scale=1080:-2[fg];[bg][fg]overlay=(W-w)/2:(H-h)/2,setsar=1[v1]")
    fc = base + ";[v1][1:v]overlay=0:0,format=yuv420p[v]"
    fo = max(0.0, length - 1.2)
    cmd = [get_ffmpeg(), "-y", "-v", "error", "-ss", f"{start:.2f}", "-t", f"{length:.2f}", "-i", src, "-i", png,
           "-filter_complex", fc, "-map", "[v]", "-map", "0:a?", "-af", f"afade=t=in:st=0:d=0.6,afade=t=out:st={fo:.2f}:d=1.2",
           "-c:v", "libx264", "-preset", "fast", "-crf", "23", "-r", "30", "-c:a", "aac", "-b:a", "160k", "-movflags", "+faststart", out]
    p = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, errors="replace",
                       creationflags=(subprocess.CREATE_NO_WINDOW if os.name == "nt" else 0))
    try:
        os.remove(png)
    except OSError:
        pass
    if p.returncode != 0:
        raise RuntimeError("쇼츠 만들기 실패: " + (p.stderr or "")[-400:])


def hms(sec):
    sec = int(sec)
    return f"{sec // 3600}:{sec % 3600 // 60:02d}:{sec % 60:02d}" if sec >= 3600 else f"{sec // 60:02d}:{sec % 60:02d}"


def music_upload_text(title, preset_names, chapters=None, minutes=None, own_audio=None):
    """음악 영상 업로드 문구 (제목 후보·설명·해시태그·고정 댓글). own_audio: 불러온 음악 파일 이름 (프로그램 작곡이 아님)"""
    P = [MUSIC_PRESETS[n] for n in preset_names if n in MUSIC_PRESETS]
    tags = [] if P else ["#힐링음악", "#수면음악", "#공부음악", "#플레이리스트", "#playlist", "#relaxingmusic"]
    for p in P:
        for tg in p["tags"].split():
            if tg not in tags:
                tags.append(tg)
    length = (f"{int(minutes // 60)}시간" if minutes and minutes >= 60 and minutes % 60 == 0
              else f"{int(minutes)}분" if minutes else "")
    titles = [f"{title}" + (f" | {length}" if length else ""),
              f"{(P[0]['desc'] if P else title).split(',')[0]} | " + (length or "") + " 🎧",
              f"[{length or 'Playlist'}] {title}"]
    lines = [title, ""]
    for p in P[:3]:
        lines.append("🎵 " + p["desc"])
    lines += ["", "공부할 때, 일할 때, 쉬거나 잠들기 전에 편하게 틀어 두세요.",
              "좋았다면 구독과 좋아요로 응원해 주세요 🙏", ""]
    if any(p["gen"] == "binaural" for p in P):
        lines += ["🎧 바이노럴 비트는 헤드폰(이어폰)으로 들어야 왼쪽·오른쪽 소리 차이가 전달됩니다. 운전 중에는 듣지 마세요.", ""]
    if chapters:
        lines += ["⏱ 목차"] + [f"{hms(t)} {n}" for t, n in chapters] + [""]
    lines += ([] if own_audio else ["※ 이 영상의 음악은 프로그램으로 직접 만든 창작 음악입니다."]) + ["※ 의학적 치료 효과를 보장하지 않습니다.", "", " ".join(tags[:12])]
    pkg = {"titles": titles, "description": "\n".join(lines), "hashtags": " ".join(tags[:12]),
           "pinned_comment": "오늘 어떤 순간에 이 음악을 틀어 두셨나요? 🎧 (공부·일·잠들기 전·명상)"}
    if own_audio:
        pkg["notes"] = (f"불러온 음악 파일: {own_audio}\n"
                        "업로드 전에 이 음악을 유튜브에 올려도 되는지(저작권·사용 허락) 꼭 확인하세요. "
                        "직접 만든 곡이 아니면 설명란에 원작자·출처를 적는 것이 좋습니다.")
    return pkg


class ItemTree(ttk.Frame):
    """체크(영상에 넣기) · 번호 · 내용 · 표시 목록. 위아래 드래그로 순서 바꾸기, ☑ 칸을 누르면 넣기/빼기"""

    def __init__(self, parent, on_select=None, on_toggle=None, on_reorder=None, height=14, width=380):
        super().__init__(parent)
        self.on_select, self.on_toggle, self.on_reorder = on_select, on_toggle, on_reorder
        self.tree = ttk.Treeview(self, columns=("chk", "no", "name", "mark"), show="headings", height=height, selectmode="browse")
        for c, t, w, anc, stretch in (("chk", "☑", 30, "center", False), ("no", "번호", 42, "e", False),
                                      ("name", "내용", max(120, width - 170), "w", True), ("mark", "표시", 80, "w", False)):
            self.tree.heading(c, text=t)
            self.tree.column(c, width=w, minwidth=w, anchor=anc, stretch=stretch)
        sb = ttk.Scrollbar(self, command=self.tree.yview)
        self.tree.configure(yscrollcommand=sb.set)
        self.tree.pack(side="left", fill="both", expand=True)
        sb.pack(side="left", fill="y")
        self.tree.tag_configure("off", foreground="#aaa")
        self.tree.tag_configure("fast", foreground="#b35900")
        self._items, self._drag = {}, None
        self.tree.bind("<Button-1>", self._press)
        self.tree.bind("<B1-Motion>", self._motion)
        self.tree.bind("<ButtonRelease-1>", self._release)
        self.tree.bind("<<TreeviewSelect>>", lambda e: self.on_select and self.on_select(self.selected()))

    def set_items(self, items, select=None):
        """items: [{"id", "checked", "no", "name", "mark", "tag"}]"""
        self.tree.delete(*self.tree.get_children())
        self._items = {}
        for it in items:
            iid = str(it["id"])
            self._items[iid] = it
            on = it.get("checked", True)
            tags = ("off",) if not on else ((it["tag"],) if it.get("tag") else ())
            self.tree.insert("", "end", iid=iid, values=("☑" if on else "☐", it.get("no", ""), it.get("name", ""), it.get("mark", "")), tags=tags)
        if select is not None and str(select) in self._items:
            self.tree.selection_set(str(select))
            self.tree.see(str(select))

    def order(self):
        return [self._items[i]["id"] for i in self.tree.get_children()]

    def selected(self):
        s = self.tree.selection()
        return self._items[s[0]]["id"] if s and s[0] in self._items else None

    def _press(self, e):
        row = self.tree.identify_row(e.y)
        self._drag = {"row": row, "y": e.y, "moved": False} if row else None
        if row and self.tree.identify_column(e.x) == "#1":       # ☑ 칸: 넣기/빼기
            it = self._items[row]
            it["checked"] = not it.get("checked", True)
            self.tree.set(row, "chk", "☑" if it["checked"] else "☐")
            self.tree.item(row, tags=(() if it["checked"] else ("off",)))
            self._drag = None
            if self.on_toggle:
                self.on_toggle(it["id"], it["checked"])
            return "break"

    def _motion(self, e):
        if not self._drag:
            return
        if not self._drag["moved"] and abs(e.y - self._drag["y"]) < 6:
            return
        target = self.tree.identify_row(e.y)
        if target and target != self._drag["row"]:
            self.tree.move(self._drag["row"], "", self.tree.index(target))
            self._drag["moved"] = True

    def _release(self, e):
        if self._drag and self._drag["moved"] and self.on_reorder:
            self.on_reorder(self.order())
        self._drag = None


